#include <array>
#include <cstddef>
#include <vector>
#include <omp.h>

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    bins.fill(0);

    const int nthreads = omp_get_max_threads();
    std::vector<std::array<size_t, 10>> local(static_cast<std::size_t>(nthreads));
    for (auto &a : local) a.fill(0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        auto &lb = local[static_cast<std::size_t>(tid)];

        #pragma omp for nowait
        for (std::size_t i = 0; i < x.size(); ++i) {
            // Values are in [0,100] inclusive. Bin into [0,10), [10,20), ..., [90,100],
            // so 100 goes into the last bin (index 9).
            int b = static_cast<int>(x[i] / 10.0);
            if (b < 0) b = 0;
            if (b > 9) b = 9;
            lb[static_cast<std::size_t>(b)]++;
        }

        #pragma omp barrier

        #pragma omp for
        for (int b = 0; b < 10; ++b) {
            size_t sum = 0;
            for (int t = 0; t < nthreads; ++t) {
                sum += local[static_cast<std::size_t>(t)][static_cast<std::size_t>(b)];
            }
            bins[static_cast<std::size_t>(b)] = sum;
        }
    }
}
